() => {
      const P = () => window.pamukkale, TICK = 0.05;
      const out = { levels: 0, won: 0, stars: 0, poolsFilled: 0, pools: 0, wasted: 0, ticks: 0 };
      document.getElementById('btn-play').click();
      for (let guard = 0; guard < 60; guard++) {
        const s = P();
        if (s.screen !== 'play') throw new Error(`gate: level ${s.level} not on the play screen (${s.screen})`);
        for (const [kind, x, y] of s.sol || []) if (!s.place(x, y, kind)) throw new Error(`gate: level ${s.level} could not place ${kind} at ${x},${y}`);
        const gsol = s.gsol || [];
        let r = s;
        if (!gsol.length) r = window.pamukkaleSim(100000);
        else for (let k = 0; k < 100000 && r.screen === 'play'; k++) { for (const [x, y, tk] of gsol) if (tk === r.tick) s.toggle(x, y); r = window.pamukkaleSim(TICK); }
        if (r.screen !== 'result') throw new Error(`gate: level ${r.level} did not finish (${r.screen})`);
        out.levels++; out.ticks += r.tick; out.wasted += r.wasted; out.pools += r.pools.total; out.poolsFilled += r.pools.filled;
        const win = r.stars && r.stars[0] !== undefined && r.pools.filled === r.pools.total;
        out.stars += (r.stars || []).filter(Boolean).length;
        if (!win) break;
        out.won++;
        document.getElementById('btn-next').click();
        if (P().screen === 'end') break;
      }
      out.wasted = Math.round(out.wasted * 10) / 10;
      window.__gateM = out;
    }
